import React, { Component } from 'react'
import { Row } from 'antd'
import axios from 'axios'
import qs from 'qs'

import { clearStorage } from '../../../../helpers/utility'
import urls from '../../../../config/urls'
import loadingGif from '../../../../image/payment-gif.gif'
import querySearchBuilder from '../../../../helpers/querySearchBuilder'

class PaymentProcessing extends Component {
  checkPaymentStatus (params) {
    console.log('params in check payment', params)
    const { history } = this.props
    const paymentStatusPayload = {
      'payment_id': params.trxId || params.order_id,
      'payment_gateway': params.src,
      'refNum': params.refNum
    }

    axios.post(urls.url.checkPaymentStatus, paymentStatusPayload)
      .then(response => {
        const {
          payment_status: paymentStatus,
          application_id: applicationId,
          product,
          email,
          phone_no: phoneNo
        } = response.data
        const queryPayload = {
          product,
          email,
          phoneNo,
          applicationId
        }
        const queryString = querySearchBuilder(queryPayload)

        switch (paymentStatus) {
          case 'SUCCESS':
          case 'SETTLEMENT':
            clearStorage()
            if (applicationId) {
              history.push({
                pathname: '/payment/success',
                search: queryString
              }, {
                params: {
                  appID: applicationId,
                  email
                }
              })
            } else {
              history.push('/payment/pending')
            }
            break
          case 'INITIATED':
          case 'PENDING':
            history.push('/payment/pending')
            break
          default:
            history.push('/payment/failure')
        }
      }).catch(error => {
        console.log(error)
        history.push('/payment/pending')
      })
  }

  componentDidMount () {
    const { history } = this.props
    let params = qs.parse(this.props.location.search.slice(1))
    if ((params.refNum && params.trxId && params.src) || params.order_id) {
      console.log('params in mount', params)
      this.checkPaymentStatus(params)
    } else {
      history.push('/payment/failure')
    }
  }

  render () {
    return (
      <Row type='flex' justify='center' style={{ marginTop: '150px' }}>
        <Row type='flex' justify='center'>
          <img src={loadingGif} height='150px' alt='loading' />
        </Row>
      </Row>
    )
  }
}

export default PaymentProcessing
